def _format_duration(seconds: float) -> str:
    seconds = max(0, round(seconds))
    hours, remainder = divmod(seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    if hours:
        return f"{hours}:{minutes:02d}:{seconds:02d}"
    return f"{minutes}:{seconds:02d}"


def _creation_flags() -> int:
    if os.name != "nt":
        return 0
    return getattr(subprocess, "CREATE_NO_WINDOW", 0)


class DocuRandomApp:
    def __init__(
        self,
        root: Tk,
        *,
        workspace: Workspace | None = None,
        workspace_store: WorkspaceStore | None = None,
        on_change_workspace: Callable[[], None] | None = None,
        flow_manager: FlowAgentManager | None = None,
        flow_coordinator: FlowGenerationCoordinator | None = None,
        render_pool: AdaptiveRenderPool | None = None,
        voicevox_controller: VoicevoxEngineController | None = None,
        youtube_uploader: YouTubeStudioUploader | None = None,
        smm_client: SmmApiClient | None = None,
        codex_precheck: _SharedCodexPrecheck | None = None,
        voicevox_precheck: _SharedVoicevoxPrecheck | None = None,
        chatgpt_turn_pool: _SharedChatGPTTurnPool | None = None,
        smart_voice_lock: object | None = None,
        disk_lock: threading.RLock | None = None,
        job_disk_reservations: dict[str, tuple[Path, int]] | None = None,
        notification_sink: Callable[[str, str], None] | None = None,
        notification_photo_sink: Callable[..., None] | None = None,
        global_render_limit_provider: Callable[[], int] | None = None,
        global_render_limit_setter: Callable[[int], int] | None = None,
        event_pump: _SharedTkEventPump | None = None,
        manage_root_protocol: bool = True,
    ) -> None:
        self.root = root
        # Tk widgets and variables are single-threaded. Background workers may
        # persist diagnostics, but they must enqueue the visible log update
        # instead of calling Tk while the main loop is servicing another lock.
        self._tk_thread_id = threading.get_ident()
        self.workspace = workspace
        self.workspace_store = workspace_store
        self.on_change_workspace = on_change_workspace
        self.owns_flow_manager = flow_manager is None
        self.flow_manager = flow_manager or FlowAgentManager()
        self.flow_coordinator = flow_coordinator or FlowGenerationCoordinator()
        self.owns_render_pool = render_pool is None
        self.owns_voicevox_controller = voicevox_controller is None
        self.youtube_uploader = youtube_uploader or YouTubeStudioUploader()
        self.smm_client = smm_client or SmmApiClient()
        self.codex_precheck = codex_precheck or _SharedCodexPrecheck()
        self.voicevox_precheck = voicevox_precheck or _SharedVoicevoxPrecheck()
        self.chatgpt_turn_pool = chatgpt_turn_pool or _SharedChatGPTTurnPool(
            1, cooldown_path=app_data_dir() / "runtime" / "chatgpt-account-cooldown.json",
        )
        self.notification_sink = notification_sink
        self.notification_photo_sink = notification_photo_sink
        self.global_render_limit_provider = global_render_limit_provider
        self.global_render_limit_setter = global_render_limit_setter
        self.event_pump = event_pump
        self.manage_root_protocol = manage_root_protocol
        if self.workspace is not None:
            # The user may have removed a broken video's Media/Output/VOICEVOX
            # files directly while the app was closed.  Reconcile that durable
            # state before loading it into Tk variables so the workspace does
            # not keep demanding Continue for files that no longer exist.
            reconcile_deleted_workspace_session(self.workspace)
            self.workspace.ensure_layout()
        self.diagnostic_log_path = (
            self.workspace.state_dir / "diagnostic.log"
            if self.workspace is not None
            else app_data_dir() / "diagnostic.log"
        )
        self.diagnostic_log_lock = threading.Lock()
        self.diagnostic_session_closed = False
        self._start_diagnostic_session()
        # Keep the native title exact so a second launcher can always find,
        # restore and foreground this single window. The workspace name is
        # rendered inside the header instead.
        self.root.title(WINDOW_TITLE)
        window_metrics = configure_responsive_window(self.root)
        self.ui_scale = window_metrics.font_scale
        self.root.configure(bg=BACKGROUND)
        resource_root = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parents[1]))
        icon_path = resource_root / "assets" / "docurandom.ico"
        if icon_path.is_file():
            try:
                self.root.iconbitmap(default=str(icon_path))
            except Exception:
                pass
        if self.manage_root_protocol:
            self.root.protocol("WM_DELETE_WINDOW", self._on_close)

        self.events: _CoalescingEventQueue = _CoalescingEventQueue()
        self.media: list[MediaInfo] = []
        self.scan_warnings: list[str] = []
        self.scanned_source = ""
        self._continuous_precheck_failure_signatures: set[tuple[str, str, str]] = set()
        self._continuous_precheck_last_scan_at = 0.0
        self.scan_token = 0
        self.audio_probe_token = 0
        self.audio_preflight_token = 0
        self.preview_token = 0
        self.scanning = False
        self.rendering = False
        self.cancelling_all = False
        self.closed = False
        self.closing_after_cancel = False
        # Set only by the explicit launcher Skip/Xóa checkpoint action.  The
        # scheduler treats this as a short-lived barrier while cooperative
        # cancellation finishes, so it cannot start a replacement video in
        # the middle of archiving the current session.
        self.explicit_skip_pending = False
        self.explicit_skip_started_at = 0.0
        self.explicit_skip_reason = ""
        self.lifecycle_cancel_event = threading.Event()
        self.scan_cancel_event = threading.Event()
        self.audio_preflight_cancel_event = threading.Event()
        self.audio_preflight_active = False
        self.audio_preflight_identity = ""
        self.audio_preflight_resume_token: int | None = None
        self.last_video: Path | None = None
        self.preview_photo: ImageTk.PhotoImage | None = None
        self.audio_duration = 0.0
        self.audio_duration_path = ""
        self.audio_duration_identity = ""
        self.history = HistoryStore(
            self.workspace.history_path if self.workspace is not None else None
        )
        self.content_history = ContentHistoryStore(
            (
                self.workspace.content_history_path
                if self.workspace is not None
                else app_data_dir() / "content_history.json"
            ),
            (
                self.workspace.content_history_text_path
                if self.workspace is not None
                else app_data_dir() / "CHECKLIST_NOI_DUNG_DA_LAM.txt"
            ),
        )
        self.identity_lock = threading.RLock()
        self.reserved_seeds = self.history.used_seeds()
        self.reserved_grain_seeds = self.history.used_grain_seeds()
        self.reserved_signatures: set[str] = set()
        self.reserved_output_hashes: set[str] = set()
        self.reserved_visual_hashes: set[str] = set()
        self.progress_aggregator = ProgressAggregator()
        self.job_widgets: dict[str, dict[str, object]] = {}
        self.job_states: dict[str, str] = {}
        self.ignored_render_job_ids: set[str] = set()
        self.job_results: dict[str, tuple[RenderResult, str, str]] = {}
        self.job_requests: dict[
            str,
            tuple[
                str,
                tuple[MediaInfo, ...],
                RenderSettings,
                SmartVoiceRequest | None,
            ],
        ] = {}
        self.disk_lock = disk_lock or threading.RLock()
        self.job_disk_reservations = (
            job_disk_reservations
            if job_disk_reservations is not None
            else {}
        )
        self.runtime_lock = threading.RLock()
        self.runtime_tools: FFmpegTools | None = None
        self.runtime_profile: RenderRuntimeProfile | None = None
        self.runtime_detecting = False
        self.audio_cache_lock = threading.RLock()
        self.audio_duration_cache: dict[str, float] = {}
        self.job_sequence = 0
        self.voicevox_controller = voicevox_controller or VoicevoxEngineController()
        self.voicevox_token = 0
        self.voicevox_cancel_event = threading.Event()
        self.voicevox_busy = False
        self.voicevox_pending_synthesis = False
        self.voicevox_error_dialog_token = 0
        self.content_error_dialog_token = 0
        self.voicevox_remote_start_pending = False
        self.voicevox_remote_notify_token = 0
        self.voicevox_styles: dict[str, VoicevoxStyle] = {}
        self.last_voicevox_path: Path | None = None
        self.voicevox_engine_state = "checking"
        self.voicevox_engine_available = False
        self.voicevox_check_activity_at = 0.0
        # One workspace never creates the same narration twice concurrently,
        # while the shared bounded semaphore lets different workspaces synthesize
        # in parallel according to the detected machine capacity.
        shared_voice_slots = smart_voice_lock or threading.BoundedSemaphore(1)
        self.smart_voice_lock = _WorkspaceVoiceGate(shared_voice_slots)
        self.smart_voice_results: dict[str, VoicevoxSynthesisResult] = {}
        self.job_voice_enabled: dict[str, bool] = {}
        # One-click narration is prepared as soon as ChatGPT finishes, in
        # parallel with Flow image generation.  It has its own cancellation
        # token because the manual VOICEVOX panel may also be used separately.
        self.pipeline_voice_token = 0
        self.pipeline_voice_busy = False
        self.pipeline_voice_cancel_event = threading.Event()
        self.pipeline_voice_result: VoicevoxSynthesisResult | None = None
        self.content_token = 0
        self.content_busy = False
        self.content_precheck_pending = False
        self.content_generation_started = False
        self.content_activity_stage = ""
        self.content_codex_ready = False
        self.content_voice_ready = False
        self.content_flow_ready = True
        self.content_cancel_event = threading.Event()
        self.content_runner: MasterPromptRunner | None = None
        self.content_cli_status: ChatGPTWebStatus | CodexCliStatus | None = None
        self.content_last_result: ContentRunResult | None = None
        self.last_content_package: Path | None = None
        # The ChatGPT conversation is scoped to the current video/package.
        # Downstream stages must reuse it instead of opening one conversation
        # per artifact.  These values are also recoverable from the content
        # checkpoint after an application restart.
        self.video_chat_thread_id = ""
        self.video_chat_response_id = ""
        self.video_chat_package: Path | None = None
