        master_scroll = ttk.Scrollbar(
            master_editor,
            orient=VERTICAL,
            command=self.master_prompt_text.yview,
        )
        self.master_prompt_text.configure(yscrollcommand=master_scroll.set)
        self.master_prompt_text.pack(side=LEFT, fill="x", expand=True)
        master_scroll.pack(side=RIGHT, fill="y")
