    def _build_smm_youtube_like_panel(self, content: ttk.Frame) -> None:
        ttk.Separator(content, orient=HORIZONTAL).pack(fill="x", pady=14)
        self._section_heading(content, "6 · TĂNG LIKE YOUTUBE QUA 1MM", "play")
        scope_card = ttk.Frame(content, style="PanelAlt.TFrame", padding=10)
